// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * From when the next instance is computed (DESIGN §9.12).
 * Mirrors [`cal_core::RecurrenceAnchor`].
 */

public enum RecurrenceAnchor: Equatable, Hashable {
    
    /**
     * Advance from the task's own date.
     */
    case fromDate
    /**
     * Advance from when the task was completed.
     */
    case fromCompletion





}

#if compiler(>=6)
extension RecurrenceAnchor: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeRecurrenceAnchor: FfiConverterRustBuffer {
    typealias SwiftType = RecurrenceAnchor

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RecurrenceAnchor {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .fromDate
        
        case 2: return .fromCompletion
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RecurrenceAnchor, into buf: inout [UInt8]) {
        switch value {
        
        
        case .fromDate:
