/**
 * Parse a calendar attendee entry into its display name and email.
 *
 * Accepts `"Display Name <email@host>"` or a bare `"email@host"`, delegating
 * the split to [`cal_core::attendee::parse`] so the mobile UI and every
 * desktop adapter share one parser.
 */
public func parseAttendee(entry: String) -> ParsedAttendee  {
    return try!  FfiConverterTypeParsedAttendee_lift(try! rustCall() {
    uniffi_cal_ffi_fn_func_parse_attendee(
        FfiConverterString.lower(entry),$0
    )
})
}
/**
 * Parse an RFC 5545 `RRULE` value into a [`TaskRecurrence`]. Tolerates a
 * leading `RRULE:` and surrounding whitespace; returns `None` when there is no
 * usable `FREQ`. Unmodelled parts are ignored.
 */
public func rruleToTaskRecurrence(rrule: String) -> TaskRecurrence?  {
    return try!  FfiConverterOptionTypeTaskRecurrence.lift(try! rustCall() {
    uniffi_cal_ffi_fn_func_rrule_to_task_recurrence(
        FfiConverterString.lower(rrule),$0
    )
})
}
/**
 * Serialize a [`TaskRecurrence`] into an RFC 5545 `RRULE` value (without the
 * `RRULE:` prefix), e.g. `FREQ=WEEKLY;INTERVAL=2;BYDAY=MO,WE`.
 *
 * Errors only if an `OnDate` end carries an unparseable date string.
 */
public func taskRecurrenceToRrule(recurrence: TaskRecurrence)throws  -> String  {
    return try  FfiConverterString.lift(try rustCallWithError(FfiConverterTypeRecurrenceError_lift) {
    uniffi_cal_ffi_fn_func_task_recurrence_to_rrule(
        FfiConverterTypeTaskRecurrence_lower(recurrence),$0
    )
})
}

